     * The plant dies permanently when it has been eaten out.
     * It is removed from the field and no longer participates in the simulation.
     */
    @Override
    protected void setDead()
    {
        lifeState = LifeState.PERMANENTLY_DEAD;
        regrowthReady = false;
        super.setDead();
    }

